(() => {
'use strict';
const $=id=>document.getElementById(id),core=()=>window.DashboardCore,community=()=>window.Community,client=()=>community()?.client,user=()=>community()?.user;
const s={uid:null,epoch:0,request:0,adminRequest:0,admin:false,ready:false,bookmarks:[],mine:[],comments:[],likes:[],controls:new Map(),tab:'bookmarks',limit:20,adminTab:'resources',adminLimit:30,adminComments:[],adminResources:[],busy:false};
const text=(tag,value,cls='')=>{const n=document.createElement(tag);n.textContent=value;n.className=cls;return n};
const button=(title,run,cls='')=>{const n=text('button',title,cls);n.type='button';n.onclick=run;return n};
const err=e=>e?.message||'불러오지 못했습니다. 새로고침 후 다시 시도해 주세요.';
const notice=t=>core().toast(t);
async function all(table,columns,filter,order='created_at',second='id') {const rows=[];for(let start=0;;start+=200){let q=client().from(table).select(columns);if(filter)q=filter(q);q=q.order(order,{ascending:false});if(second!==order)q=q.order(second,{ascending:false});const r=await q.range(start,start+199);if(r.error)throw r.error;rows.push(...r.data||[]);if((r.data||[]).length<200)return rows}}
function cleanSnapshot(row){try{const url=core().validURL(row.url);if(!/^[a-f0-9]{24}$/.test(row.id))return null;return {id:row.id,url,title:String(row.title||'저장한 자료').slice(0,250),source:String(row.source||'자료').slice(0,80),summary:String(row.summary||'').slice(0,1000),...core().cleanOverride(row),collected_at:row.collected_at||row.created_at||null,published_at:row.published_at||null,archived:true}}catch{return null}}
function snapshots(){return s.bookmarks.map(b=>cleanSnapshot({...b.snapshot,id:b.resource_id})).filter(Boolean)}
function applyControl(row){const c=s.controls.get(row.id);return c?{...core().applyOverride(row,c.overrides),hidden:c.hidden}:row}
function resolve(id){const row=core().effectiveResources().find(r=>r.id===id)||snapshots().find(r=>r.id===id)||s.mine.find(r=>r.id===id);return row&&!s.controls.get(id)?.hidden?applyControl(row):null}
async function loadControls(){if(!client())return;const rows=await all('defi_resource_controls','*',null,'resource_id','resource_id');s.controls=new Map(rows.map(r=>[r.resource_id,r]))}
async function refresh(){if(!client())return;const epoch=s.epoch,request=++s.request,id=user()?.id;try{await loadControls();if(epoch!==s.epoch||request!==s.request)return;if(!id){s.ready=true;core().render();renderMine();return}const [role,b,m,c,l]=await Promise.all([client().rpc('defi_is_admin'),all('defi_bookmarks','*',q=>q.eq('user_id',id),'created_at','resource_id'),all('defi_resources','*,defi_profiles(display_name)',q=>q.eq('owner_id',id)),all('defi_comments','*,defi_profiles(display_name)',q=>q.eq('author_id',id)),all('defi_likes','resource_id,created_at',q=>q.eq('user_id',id),'created_at','resource_id')]);if(epoch!==s.epoch||request!==s.request||id!==user()?.id)return;for(const r of [role])if(r.error)throw r.error;s.admin=role.data===true;s.bookmarks=b;s.mine=m.map(r=>({...r,community:true,contributor:r.defi_profiles?.display_name||'이용자',collected_at:r.created_at}));s.comments=c;s.likes=l;s.ready=true;$('my-error').textContent='';$('admin-nav').hidden=!s.admin;renderAdmin();core().render();renderMine();if(location.hash==='#admin')await openAdmin()}catch(e){if(epoch===s.epoch&&request===s.request)$('my-error').textContent=err(e)}}
async function authChanged(){s.epoch++;s.request++;s.adminRequest++;s.uid=user()?.id||null;s.admin=false;s.ready=false;s.bookmarks=[];s.mine=[];s.comments=[];s.likes=[];s.adminComments=[];s.adminResources=[];s.limit=20;$('admin-nav').hidden=true;$('admin-list').replaceChildren();$('admin-content').hidden=true;$('admin-gate').hidden=false;$('my-list').replaceChildren();renderMine();core().render();await refresh()}
async function toggleBookmark(id){if(!user()){community().openAuth();return}if(!s.ready){notice('계정 정보를 불러오는 중입니다. 잠시 후 다시 시도해 주세요.');return}if(s.busy)return;const uid=user().id,epoch=s.epoch,old=s.bookmarks.find(r=>r.resource_id===id);s.busy=true;try{let r;if(old)r=await client().from('defi_bookmarks').delete().eq('user_id',uid).eq('resource_id',id).select('resource_id');else{const row=resolve(id),snapshot=row&&cleanSnapshot(row);if(!snapshot)throw Error('저장할 자료를 찾지 못했습니다.');r=await client().from('defi_bookmarks').insert({user_id:uid,resource_id:id,snapshot}).select('resource_id')}if(r.error&&r.error.code!=='23505')throw r.error;if(epoch!==s.epoch)return;await refresh();notice(old?'북마크를 해제했습니다.':'북마크를 계정에 저장했습니다.')}catch(e){notice(err(e))}finally{s.busy=false}}
async function importBookmarks(){if(!user()||s.busy)return;s.busy=true;$('import-bookmarks').disabled=true;const uid=user().id,epoch=s.epoch;let saved=0;try{for(const id of [...core().state.saved]){if(epoch!==s.epoch||uid!==user()?.id)break;const row=core().effectiveResources().find(r=>r.id===id),snapshot=row&&cleanSnapshot(row);if(!snapshot)continue;const r=await client().from('defi_bookmarks').insert({user_id:uid,resource_id:id,snapshot});if(r.error&&r.error.code!=='23505')throw r.error;if(epoch!==s.epoch)break;core().state.saved=core().state.saved.filter(x=>x!==id);core().store();saved++}await refresh();notice(saved+'건을 현재 계정으로 가져왔습니다.')}catch(e){notice(err(e))}finally{s.busy=false;$('import-bookmarks').disabled=false}}
async function unlike(id){if(!user())return;const uid=user().id,r=await client().from('defi_likes').delete().eq('user_id',uid).eq('resource_id',id);if(r.error){notice(err(r.error));return}community().forgetLike(id);await refresh()}
function renderMine(){const logged=!!user();$('my-gate').hidden=logged;$('my-content').hidden=!logged;if(!logged){$('my-list').replaceChildren();return}$('my-name').textContent=community().profile?.display_name||'내 계정';$('my-email').textContent=user().email||'';$('bookmark-import').hidden=!core().state.saved.length;$('my-interests-summary').textContent='관심 협의회: '+(community().interests.map(id=>core().state.catalog.councils.find(c=>c.id===id)?.label||id).join(', ')||'아직 설정하지 않았어요.');$('my-tabs').replaceChildren();for(const [id,label,rows]of [['bookmarks','북마크',s.bookmarks],['mine','내 자료',s.mine],['comments','내 댓글',s.comments],['likes','유용해요',s.likes]]){const b=button(label+' '+rows.length,()=>{s.tab=id;s.limit=20;renderMine()},s.tab===id?'active':'');b.setAttribute('aria-pressed',String(s.tab===id));$('my-tabs').append(b)}const list=$('my-list');list.replaceChildren();if(!s.ready){list.append(text('p','내 활동을 불러오는 중입니다.','note'));$('my-more').hidden=true;return}const rows=s[s.tab];if(!rows.length)list.append(text('div',{bookmarks:'다시 읽고 싶은 자료의 ☆ 버튼을 눌러보세요.',mine:'자료 모아보기에서 첫 자료를 공유해보세요.',comments:'자료의 댓글 버튼을 눌러 의견을 남겨보세요.',likes:'도움이 된 자료에 유용해요를 눌러보세요.'}[s.tab],'member-empty'));for(const r of rows.slice(0,s.limit)){const id=r.resource_id||r.id,row=resolve(id);if(s.tab==='comments'){const article=text('article','','activity-row');article.append(text('small',new Date(r.created_at).toLocaleString('ko-KR')+(r.hidden?' · 관리자 숨김':'')),text('p',r.body));article.append(button(row?.title||'현재 목록에 없는 자료',()=>{if(row)community().openThread(row);else notice('원래 자료가 현재 수집 목록에 없습니다. 아래에서 댓글을 삭제할 수 있습니다.')}),button('댓글 삭제',async()=>{await community().removeComment(r);await refresh()}));list.append(article)}else if(row){const card=core().resourceCard(row);if(s.tab==='likes')card.append(button('유용해요 취소',async()=>{await unlike(id)},'activity-remove'));if(s.tab==='mine'&&s.controls.get(id)?.hidden)card.append(text('p','관리자 숨김','note'));list.append(card)}else{const box=text('article','','activity-row');box.append(text('b',s.controls.get(id)?.hidden?'관리자가 숨긴 자료입니다.':'현재 목록에 없는 자료입니다.'));if(s.tab==='bookmarks')box.append(button('북마크 해제',()=>toggleBookmark(id)));if(s.tab==='likes')box.append(button('유용해요 취소',async()=>{await unlike(id)}));if(s.tab==='mine'){box.append(text('p',r.title),button('자료 삭제',async()=>{await community().deleteResource(r);await refresh()}))}list.append(box)}}$('my-more').hidden=rows.length<=s.limit}
function openMine(){core().navigate('mypage');renderMine();refresh()}
async function openAdmin(){core().navigate('admin');const epoch=s.epoch,request=++s.adminRequest;try{if(!user()){s.admin=false;renderAdmin();return}const role=await client().rpc('defi_is_admin');if(role.error)throw role.error;if(epoch!==s.epoch||request!==s.adminRequest)return;s.admin=role.data===true;$('admin-nav').hidden=!s.admin;renderAdmin();if(!s.admin)return;$('admin-count').textContent='관리 대상을 불러오는 중입니다.';const [comments,resources]=await Promise.all([all('defi_comments','*,defi_profiles(display_name)'),all('defi_resources','*,defi_profiles(display_name)')]);if(epoch!==s.epoch||request!==s.adminRequest||!user())return;s.adminComments=comments;s.adminResources=resources.map(r=>({...r,community:true,collected_at:r.created_at}));$('admin-error').textContent='';renderAdmin()}catch(e){if(epoch===s.epoch)$('admin-error').textContent=err(e)}}
function renderAdmin(){const allowed=!!user()&&s.admin;$('admin-gate').hidden=allowed;$('admin-content').hidden=!allowed;if(!allowed){$('admin-list').replaceChildren();return}$('admin-tabs').replaceChildren();for(const [id,label]of [['resources','자료 관리'],['comments','댓글 관리']]){const b=button(label,()=>{s.adminTab=id;s.adminLimit=30;renderAdmin()},s.adminTab===id?'active':'');b.setAttribute('aria-pressed',String(s.adminTab===id));$('admin-tabs').append(b)}const map=new Map(core().state.resources.map(r=>[r.id,r]));for(const r of s.adminResources)if(!map.has(r.id))map.set(r.id,r);const query=$('admin-search').value.trim().toLowerCase(),status=$('admin-status').value;let rows=s.adminTab==='comments'?s.adminComments:[...map.values()];rows=rows.filter(r=>{const hidden=s.adminTab==='comments'?r.hidden:!!s.controls.get(r.id)?.hidden;return(status==='all'||hidden===(status==='hidden'))&&(!query||(s.adminTab==='comments'?(r.body+' '+r.defi_profiles?.display_name):(r.title+' '+r.source)).toLowerCase().includes(query))});$('admin-count').textContent=rows.length+'건 · 숨김 상태는 서버에 저장됩니다.';$('admin-list').replaceChildren();if(!rows.length)$('admin-list').append(text('div','조건에 맞는 항목이 없습니다.','member-empty'));for(const row of rows.slice(0,s.adminLimit)){const isComment=s.adminTab==='comments',hidden=isComment?row.hidden:!!s.controls.get(row.id)?.hidden,article=text('article','','admin-row'),head=text('div','','admin-row-head');head.append(text('span',hidden?'숨김':'공개',hidden?'status-hidden':'status-visible'),text('small',isComment?(row.defi_profiles?.display_name||'이용자'):(row.community?'이용자 공유':'RSS / 연구원 자료')));article.append(head,text('h3',isComment?'댓글':applyControl(row).title),text('p',isComment?row.body:row.source));const tools=text('div','','member-tools');if(!isComment){try{const a=text('a','원문 ↗');a.href=core().validURL(row.url);a.target='_blank';a.rel='noopener';tools.append(a)}catch{}tools.append(button('편집',()=>core().openEditor(applyControl(row))))}tools.append(button(hidden?'다시 공개':'숨기기',()=>moderate(row,isComment?'comment-status':'resource-status',!hidden)));if(isComment||row.community)tools.append(button('삭제',()=>moderate(row,isComment?'comment-delete':'resource-delete'),'danger-text'));article.append(tools);$('admin-list').append(article)}$('admin-more').hidden=rows.length<=s.adminLimit}
async function checkAdmin(){if(!user())throw Error('관리자 로그인이 필요합니다.');const r=await client().rpc('defi_is_admin');if(r.error)throw r.error;if(r.data!==true){s.admin=false;renderAdmin();throw Error('관리자 권한이 없습니다.')}}
async function moderate(row,action,value){if(s.busy)return;if(action.endsWith('delete')&&!window.confirm(action==='resource-delete'?'이 공유 자료와 연결된 모든 댓글·유용해요·북마크를 영구 삭제할까요?':'이 댓글을 영구 삭제할까요?'))return;s.busy=true;try{await checkAdmin();let r;if(action==='resource-status')r=await client().from('defi_resource_controls').upsert({resource_id:row.id,hidden:value,overrides:s.controls.get(row.id)?.overrides||{}},{onConflict:'resource_id'}).select('resource_id');else if(action==='comment-status')r=await client().from('defi_comments').update({hidden:value}).eq('id',row.id).select('id');else r=await client().from(action==='comment-delete'?'defi_comments':'defi_resources').delete().eq('id',row.id).select('id');if(r.error)throw r.error;if(!r.data?.length)throw Error('변경된 항목이 없습니다. 권한 또는 새로고침을 확인해 주세요.');await community().loadPublic();await refresh();notice(action.endsWith('delete')?'삭제했습니다.':value?'숨겼습니다.':'다시 공개했습니다.')}catch(e){$('admin-error').textContent=err(e)}finally{s.busy=false}}
async function saveEditorial(fields,row){await checkAdmin();const control=s.controls.get(row.id);const r=await client().from('defi_resource_controls').upsert({resource_id:row.id,hidden:!!control?.hidden,overrides:core().cleanOverride(fields)},{onConflict:'resource_id'}).select('resource_id');if(r.error)throw r.error;if(!r.data?.length)throw Error('저장하지 못했습니다.');await refresh();notice('자료 편집을 전체 방문자에게 반영했습니다.')}
$('my-login').onclick=()=>community().openAuth();$('my-refresh').onclick=refresh;$('my-settings').onclick=()=>{$('profile-name').value=community().profile?.display_name||'이용자';$('profile-error').textContent='';$('profile-dialog').showModal()};$('my-interests').onclick=()=>$('interest-settings').onclick();$('my-more').onclick=()=>{s.limit+=20;renderMine()};$('import-bookmarks').onclick=importBookmarks;
$('admin-refresh').onclick=refresh;$('admin-search').oninput=()=>{s.adminLimit=30;renderAdmin()};$('admin-status').onchange=()=>{s.adminLimit=30;renderAdmin()};$('admin-more').onclick=()=>{s.adminLimit+=30;renderAdmin()};
window.addEventListener('hashchange',()=>{if(location.hash==='#mypage')openMine();if(location.hash==='#admin')openAdmin()});
window.Member={get savedIDs(){return user()?s.bookmarks.map(b=>b.resource_id):core().state.saved},get connected(){return !!client()},get isAdmin(){return s.admin&&!!user()},get archivedResources(){return snapshots()},applyControl,authChanged,refresh,openMine,renderMine,toggleBookmark,saveEditorial};
renderMine();if(client())authChanged();
})();
